SELECT id, order_id, carrier, shipped_date, delivered_date, cost, status, NTILE(10) OVER w_hist AS cost_bucket, DENSE_RANK() OVER (ORDER BY cost NULLS FIRST) AS cost_dense_rank, DENSE_RANK() OVER (PARTITION BY carrier ORDER BY cost) AS cost_dense_rank_2, ROUND(cost / SUM(cost) OVER (PARTITION BY status), 4) AS cost_share, ROW_NUMBER() OVER (ORDER BY delivered_date, id) AS row_seq FROM shipments WINDOW w_hist AS (PARTITION BY status ORDER BY cost, id);
